def can_form_interval(n, m, colors, k_counts):
    # Create a frequency array for each color
    color_freq = [0] * m
    for color in colors:
        color_freq[color - 1] += 1

    # Create a frequency array for the remaining colors
    remaining_colors = [0] * m
    for i in range(m):
        if k_counts[i] > 0:
            remaining_colors[i] += k_counts[i] - 1
        else:
            remaining_colors[i] -= k_counts[i + 1] - 1

    # Create a frequency array for the leftmost window
    left_window_freq = [0] * m
    for i in range(m):
        if k_counts[i] > 0:
            remaining_colors[i] += k_counts[i] - 1
        left_window_freq[i] -= k_counts[i + 1] - 1

    # Check if the leftmost window has enough remaining colors
    if any(remaining_colors[i] < 0 for i in range(m)):
        return "NO"

    # Check if the remaining colors can be covered by the remaining windows
    remaining_remaining_colors = [0] * m
    for i in range(m):
        remaining_remaining_colors[i] = remaining_colors[i]

    for i in range(n - m + 1):
        # Update the leftmost window
        if left_window_freq[colors[i - 1] - 1] > 0:
            left_window_freq[colors[i - 1] - 1] -= 1

        # Update the remaining remaining colors
        for j in range(m):
            remaining_remaining_colors[j] += color_freq[j]

        # Check if the remaining remaining colors can be covered by the remaining windows
        for j in range(m):
            if remaining_remaining_colors[j] < 0:
                return "NO"

    return "YES"

